	'tpl_404_h' => 'Diese Seite ist nicht auf der Karte.',
	'tpl_404_p' => 'Nutzen Sie das Menü oder kehren Sie zur Startseite zurück.',
	'tpl_none' => 'Noch keine Berichte vorhanden.',
	'tpl_stories' => 'Berichte',
	'visit_addr' => 'Bay 4, Hollins Freight Park, Carrow Lane, Ashby Vale AV3 7QN',
	'visit_b1' => 'Eignungstest buchen',
	'visit_b2' => 'Besichtigungstermine',
	'visit_body' => 'Kommen Sie an jedem ersten Samstag im Monat zwischen 09:00 und 12:00 Uhr auf unser Übungsgelände. Steigen Sie ins Fahrerhaus, sehen Sie sich den Rangierbereich an und sprechen Sie mit den Ausbildern über den Kurs, der zu Ihnen passt.',
	'visit_h' => 'Kommen Sie direkt zu uns auf das Übungsgelände.',
	'visit_hours' => 'Übungsgelände Mo–Sa 07:00–17:30 · Büro Mo–Fr 08:30–17:00',
	'visit_k' => 'Besuch',
	'weeks_body' => 'Unser siebenwöchiger Ausbildungsplan führt Sie von der ersten Einstufungsfahrt über das Theorie-Coaching bis hin zur intensiven Praxis auf dem Betriebshof und auf der Straße. Wir bieten jährlich sechs Lehrgänge mit jeweils zwölf Plätzen und zwei Fahrschülern pro Fahrzeug an. Der Termin für Ihre praktische Prüfung wird direkt am Tag der Anmeldung gebucht – so haben Sie vom ersten Tag an ein festes Ziel.',
	'weeks_h' => 'Sieben Wochen von der Anmeldung bis zum Prüfungstag.',
	'weeks_k' => 'Ausbildungsablauf',
	'weeks_link' => 'Wie die Wochen ablaufen →',
	'wk_row0' => 'Bevor Sie sich für einen Kurs entscheiden, verbringen Sie zwei Stunden mit einem unserer Fahrlehrer in einem Solo-Lkw. Wir beobachten, wie Sie die Straße lesen, die Spiegel nutzen und die Fahrzeugbreite einschätzen, und besprechen anschließend, welcher Weg zu Ihnen passt. Die Gebühr wird bei Buchung eines Kurses innerhalb von 30 Tagen angerechnet.',
	'wk_row1' => 'Priya Natarajan bucht Ihre Untersuchung der Gruppe 2 bei einem zugelassenen Arzt und hilft Ihnen beim Ausfüllen des D4-Formulars sowie beim Antrag auf Ihre vorläufige Fahrerlaubnis. An zwei Abenden nehmen Sie in einer kleinen Gruppe in unserem Unterrichtsraum am Theorie- und Gefahrenwahrnehmungs-Coaching teil, mit Übungsfragen und kurzen Videoclips zur gemeinsamen Besprechung.',
	'wk_row2' => 'Sobald Sie Ihre Prüfungen in Theorie und Gefahrenwahrnehmung bestanden haben, bestätigt Priya Ihren praktischen Prüfungstermin bei der Prüfbehörde. Dieser ist bereits für Woche 7 vorgemerkt, sodass ab diesem Moment jede Fahrstunde ein festes Ziel hat und Sie genau wissen, auf welchen Tag Sie hinarbeiten.',
	'wk_row3' => 'Zwei Tage auf dem Betriebshof mit zwei Fahrschülern pro Lkw. Sie beginnen jeden Morgen mit der Abfahrtskontrolle, lernen das An- und Abkuppeln, falls Sie für die Klasse C+E trainieren, und üben das Rückfahrmanöver zwischen Leitkegeln, bis die Parkbucht ihre Enge verliert. Ilse Brandt beobachtet das Geschehen von der Seite und greift nur ein, wenn es nötig ist.',
	'wk_row4' => 'Zwei Tage auf der Straße mit Ihrem Fahrlehrer: Stadtzentrum von Ashby Vale, die Schnellstraße und eine ländliche Runde mit engen Kurven. Sie wechseln zwischen Fahren und Beobachten ab, sodass Sie auf dem Beifahrersitz ebenso wie am Steuer lernen, und jeder Tag endet mit einer kurzen Nachbesprechung.',
	'wk_row5' => 'Eine Fahrt in voller Prüfungslänge unter Prüfungsbedingungen mit einem zweiten Fahrlehrer, der Sie nicht unterrichtet hat. Er bewertet Sie wie die Prüfbehörde und gibt Ihnen eine kurze Liste mit Punkten an die Hand, die Sie vor Woche 7 noch verfeinern sollten. Die meisten Fahrschüler stellen fest, dass dies dem eigentlichen Tag jede Überraschung nimmt.',
	'wk_row6' => 'Sie treffen frühzeitig zu einer Einfahrfahrt in dem Lkw ein, auf dem Sie ausgebildet wurden, und legen anschließend Ihre praktische Prüfung ab: Fragen zur Fahrzeugsicherheit, das Rückfahrmanöver und eine Prüfungsfahrt im Straßenverkehr. Wir buchen die Prüfung direkt am Tag Ihrer Anmeldung, sodass Sie dem Termin nie nachgehen müssen.',
	'wk_rows_h' => 'Was in jeder Woche geschieht',
	'wk_rows_k' => 'Woche für Woche',
);
